import type { Person } from './person-model';

export const GlobalSettingValueTypeKeyToLabel = {
  'Text': 'Text',
  'WholeNumber': 'Whole Number',
  'Decimal': 'Decimal',
  'YesNo': 'Yes/No',
  'JSON': 'JSON'
} as const;
export type GlobalSettingValueTypeKey = keyof typeof GlobalSettingValueTypeKeyToLabel;

export interface GlobalSetting {
  /**
   * @displayName Global Setting ID
   * @description Unique system identifier - GUID generated by system
   * @uiConstraints NEVER create input fields for this ID
   */
  id: string;
  /**
   * @displayName Setting Key
   * @description Human-readable record identifier
   * @validationRule Required for create/update operations
   */
  settingKey: string;
  /**
   * @displayName Description
   * @validationRule Required for create/update operations
   */
  description: string;
  /**
   * @displayName Updated At
   * @validationRule Required for create/update operations
   */
  updatedAt: string;
  /**
   * @displayName Updated By
   * @validationRule Required for create/update operations
   */
  updatedBy: Pick<Person, 'id' | 'displayName'>;
  /**
   * @displayName Value
   * @validationRule Required for create/update operations
   */
  value: string;
  /**
   * @displayName Value Type
   * @validationRule Required for create/update operations
   */
  valueTypeKey: GlobalSettingValueTypeKey;
}

export const _GlobalSetting = 'GlobalSetting' as const;